/** Observes [Garble] one operation at a time; tests compare it with the spec's step trace. */
internal fun interface GarbleTrace {
    /** Operation [op] (numbered as in the spec) wrote [value]: a byte, or a 32-bit scratch variable. */
    fun written(
        op: Int,
        value: UInt,
    )
}

private operator fun ByteArray.get(index: UInt): UInt = (this[index.toInt()].toInt() and 0xFF).toUInt()

private operator fun ByteArray.set(
    index: UInt,
    value: UInt,
) {
    this[index.toInt()] = value.toByte()
}

/** 8-bit left rotate of the low byte of [v]; 8-bit result. */
private fun rol8(
    v: UInt,
    c: UInt,
): UInt = ((v shl c.toInt()) and 0xFFu) or ((v and 0xFFu) shr (8 - c.toInt()))

/** Like [rol8] but the left-shifted part is not masked to 8 bits. */
private fun rol8x(
    v: UInt,
    c: UInt,
): UInt = (v shl c.toInt()) or ((v and 0xFFu) shr (8 - c.toInt()))

/** 8-bit right rotate with a 32-bit result; 0 when [c] is 0. */
private fun weirdRor8(
    v: UInt,
    c: UInt,
): UInt = if (c == 0u) 0u else ((v shr c.toInt()) and 0xFFu) or ((v and 0xFFu) shl (8 - c.toInt()))

/** 8-bit left rotate with an 8-bit result; 0 when [c] is 0. */
private fun weirdRol8(
    v: UInt,
    c: UInt,
): UInt = if (c == 0u) 0u else ((v shl c.toInt()) and 0xFFu) or ((v and 0xFFu) shr (8 - c.toInt()))

/** `(v << c) ^ (v >> (8 - c))` on 32 bits; 0 when [c] is 0. */
private fun weirdRol32(
    v: UInt,
    c: UInt,
): UInt = if (c == 0u) 0u else (v shl c.toInt()) xor (v shr (8 - c.toInt()))
